class ConsistentHashRing {
  private ring = new Map<number, string>();
  private sortedKeys: number[] = [];

  addNode(node: string, vnodes = 100) {
    for (let i = 0; i < vnodes; i++) {
      const hash = murmurHash(`${node}#${i}`);
      this.ring.set(hash, node);
      this.sortedKeys.push(hash);
    }
    this.sortedKeys.sort((a, b) => a - b);
  }
}

class TokenBucket {
  private tokens: number;
  private lastRefill = Date.now();
  constructor(private capacity: number, private refillRatePerSec: number) {
    this.tokens = capacity;
  }
  allowRequest(tokensRequired = 1): boolean {
    const now = Date.now();
    this.tokens = Math.min(this.capacity, this.tokens + ((now - this.lastRefill)/1000) * this.refillRatePerSec);
    this.lastRefill = now;
    if (this.tokens >= tokensRequired) { this.tokens -= tokensRequired; return true; }
    return false;
  }
}

